<?= $this->extend(ADMIN_VIEW . 'layout') ?>
<?= $this->section('main-content') ?>
<main class="dashboard-container p-3">
    <?= view('templates/_breadcrumb', ['module' => 'admin', 'menu_title' => 'Administration', 'page' => 'Users, Roles & Permissions']) ?>
    <?= display_session_msg() ?>
    <div class="card mb-4"><div class="card-header"><h5 class="mb-0">Users</h5></div><div class="card-body"><form id="user-form" class="form-row"><?= csrf_field() ?><input type="hidden" name="id"><div class="col-md-2"><input class="form-control mb-2" name="username" placeholder="Username" required></div><div class="col-md-2"><input class="form-control mb-2" type="password" name="password" placeholder="Password (10+ chars)"></div><div class="col-md-2"><input class="form-control mb-2" name="email" placeholder="Email"></div><div class="col-md-2"><input class="form-control mb-2" name="mobile" placeholder="Mobile"></div><div class="col-md-2"><select class="form-control mb-2" name="doctor_id"><option value="0">No doctor scope</option><?php foreach ($doctors as $doctor): ?><option value="<?= (int) $doctor['id'] ?>">Dr. <?= esc($doctor['first_name'] . ' ' . $doctor['last_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><select class="form-control mb-2" name="status"><option value="1">Active</option><option value="0">Disabled</option></select></div><div class="col-md-10"><select class="form-control mb-2" name="role_ids[]" multiple required><?php foreach ($roles as $role): ?><option value="<?= (int) $role['id'] ?>"><?= esc($role['role_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button type="button" class="btn btn-primary save-user">Create user</button></div></form><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Username</th><th>Email</th><th>Roles</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= esc($user['username']) ?></td><td><?= esc($user['email'] ?? '') ?></td><td><?= esc($user['role_names'] ?? '—') ?></td><td><?= (int) $user['status'] === 1 ? 'Active' : 'Disabled' ?></td><td><button class="btn btn-sm btn-outline-secondary edit-user" data-user='<?= esc(json_encode($user), 'attr') ?>'>Edit</button> <button class="btn btn-sm btn-outline-danger delete-user" data-id="<?= (int) $user['id'] ?>">Disable</button></td></tr><?php endforeach; ?></tbody></table></div></div></div>
    <div class="row"><div class="col-lg-6"><div class="card mb-4"><div class="card-header"><h5 class="mb-0">Roles</h5></div><div class="card-body"><form id="role-form"><?= csrf_field() ?><input type="hidden" name="id"><input class="form-control mb-2" name="role_name" placeholder="Role name" required><input class="form-control mb-2" name="role_code" placeholder="ROLE_CODE" required><textarea class="form-control mb-2" name="description" placeholder="Description"></textarea><label><input type="checkbox" name="status" value="1" checked> Active</label><button type="button" class="btn btn-primary btn-sm save-role ml-2">Save role</button></form><ul class="list-group mt-3"><?php foreach ($allRoles as $role): ?><li class="list-group-item d-flex justify-content-between"><span><?= esc($role['role_name']) ?> <small class="text-muted"><?= esc($role['role_code']) ?></small></span><?php if (! (int) $role['is_system']): ?><button class="btn btn-sm btn-outline-danger delete-role" data-id="<?= (int) $role['id'] ?>">Disable</button><?php else: ?><small>System role</small><?php endif; ?></li><?php endforeach; ?></ul></div></div></div>
    <div class="col-lg-6"><div class="card mb-4"><div class="card-header"><h5 class="mb-0">Permissions and role assignment</h5></div><div class="card-body"><form id="role-permission-form"><?= csrf_field() ?><select class="form-control mb-2" name="role_id" required><option value="">Select role</option><?php foreach ($allRoles as $role): ?><?php $assigned = array_map('intval', array_column(array_filter($rolePermissions, static fn ($row) => (int) $row['role_id'] === (int) $role['id']), 'permission_id')); ?><option value="<?= (int) $role['id'] ?>" data-permissions="<?= esc(json_encode($assigned), 'attr') ?>"><?= esc($role['role_name']) ?></option><?php endforeach; ?></select><select class="form-control mb-2" name="permission_ids[]" multiple required><?php foreach ($permissions as $permission): ?><option value="<?= (int) $permission['id'] ?>"><?= esc($permission['permission_key']) ?></option><?php endforeach; ?></select><button type="button" class="btn btn-outline-primary btn-sm assign-permissions">Replace role permissions</button></form><hr><form id="permission-form"><?= csrf_field() ?><input type="hidden" name="id"><input class="form-control mb-2" name="module" placeholder="Module" required><input class="form-control mb-2" name="permission_name" placeholder="Permission name" required><input class="form-control mb-2" name="permission_key" placeholder="resource.action" required><textarea class="form-control mb-2" name="description" placeholder="Description"></textarea><label><input type="checkbox" name="status" value="1" checked> Active</label><button type="button" class="btn btn-primary btn-sm save-permission ml-2">Save permission</button></form><div class="table-responsive mt-3"><table class="table table-sm"><thead><tr><th>Module</th><th>Key</th><th>Status</th></tr></thead><tbody><?php foreach ($permissions as $permission): ?><tr><td><?= esc($permission['module']) ?></td><td><?= esc($permission['permission_key']) ?></td><td><?= (int) $permission['status'] === 1 ? 'Active' : 'Disabled' ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></div>
</main>
<?= $this->endSection() ?>
<?= $this->section('scripts') ?><script>
$(function(){const post=(url,data)=>ajaxRequest({url:url,data:data,success:function(r){if(r.status){showSuccess(r.msg);reload_page(700);}else{showError(r.msg);}}});$('.save-user').on('click',function(){const f=$('#user-form');post('<?= base_url('admin/access/users/create') ?>',f.serialize());});$('.save-role').on('click',function(){post('<?= base_url('admin/access/roles/save') ?>',$('#role-form').serialize());});$('.save-permission').on('click',function(){post('<?= base_url('admin/access/permissions/save') ?>',$('#permission-form').serialize());});$('.role-permission-role').on('change',function(){const ids=JSON.parse($(this).find(':selected').attr('data-permissions')||'[]');$('#role-permission-form [name="permission_ids[]"] option').prop('selected',false).filter(function(){return ids.indexOf(parseInt(this.value,10))!==-1;}).prop('selected',true);});$('.assign-permissions').on('click',function(){const f=$('#role-permission-form');const role=f.find('[name=role_id]').val();if(role)post('<?= base_url('admin/access/roles') ?>/'+role+'/permissions',f.serialize());});$('.delete-user').on('click',function(){if(confirm('Disable this user?'))post('<?= base_url('admin/access/users/delete') ?>/'+$(this).data('id'),{csrf_rtn:$('input[name="csrf_rtn"]').first().val()});});$('.delete-role').on('click',function(){if(confirm('Disable this role?'))post('<?= base_url('admin/access/roles/delete') ?>/'+$(this).data('id'),{csrf_rtn:$('input[name="csrf_rtn"]').first().val()});});$('.edit-user').on('click',function(){const u=$(this).data('user');const f=$('#user-form');f.find('[name=id]').val(u.id);f.find('[name=username]').val(u.username);f.find('[name=email]').val(u.email);f.find('[name=mobile]').val(u.mobile);f.find('[name=doctor_id]').val(u.doctor_id||0);f.find('[name=status]').val(u.status);f.find('[name="role_ids[]"]').val((u.role_ids||'').split(',').filter(Boolean));f.find('.save-user').text('Update user').off('click').on('click',function(){post('<?= base_url('admin/access/users/update') ?>/'+u.id,f.serialize());});});});
</script><script>$(function(){$('#role-permission-form [name="role_id"]').on('change',function(){const ids=JSON.parse($(this).find(':selected').attr('data-permissions')||'[]');$('#role-permission-form [name="permission_ids[]"] option').prop('selected',false).filter(function(){return ids.indexOf(parseInt(this.value,10))!==-1;}).prop('selected',true);});});</script><?= $this->endSection() ?>
